+static void test_strconcat(void)
+{
+    wmem_allocator_t   *allocator;
+    char               *new_str;
+
+    allocator = wmem_allocator_new(WMEM_ALLOCATOR_BLOCK);
+
+    new_str = wmem_strconcat(allocator, "ABC", NULL);
